if(path==='/api/public/hospital-status'&&method==='GET'){
 const rows=await db.prepare('SELECT hospital_id,status,services,updated_at FROM hospital_settings').all();
 const settings={};
 for(const row of(rows.results||[])){
  if(!IDS.has(row.hospital_id))continue;
  let services=[];
  try{const parsed=JSON.parse(row.services||'[]');if(Array.isArray(parsed))services=parsed.filter(x=>typeof x==='string').slice(0,20)}catch{}
  settings[row.hospital_id]={status:row.status,services,updatedAt:row.updated_at};
 }
 return json({settings,asOf:now()});
}
